insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h6', 'Envios comportamentais', 'A partir do comportamento do cliente são enviados os produtos com que ele interagiu + recomendações baseadas em inteligência.', array['migracao']::text[], 'a-avaliar', null, null, array['Abandonou o Carrinho e Não Comprou Nada','Abandonou o Carrinho e Não Levou o Item','Aniversário','Assinou a Newsletter','Avise-me','Buscou um Produto e Não Comprou','Clientes que nunca compraram','Decididos: Visitou o Mesmo Produto Várias Vezes','Deixou de Acessar o Site por 7 Dias','Fidelidade: Clientes fiéis','Inativos: Parou de Abrir Campanhas','Indecisos: Navegou em Vários Produtos sem Comprar','Navegou na Última Hora','Navegou na Última Semana','Navegou no Último Mês','Novidades na Lista de Desejos','Novidades: Novos Produtos na Loja','Novos Cadastros','Pessoas ativas: Acessou o Site nos Últimos 120 Dias','Pessoas engajadas: Acessou o Site nos Últimos 7 Dias','Pessoas inativas: Deixou de Acessar o Site por 120 Dias','Pessoas que compraram há 7 dias','Pós Compra','Reconquista: parou de comprar','Recorrência: Comprou um Produto de Uso Contínuo','Redução de Preços Similares: Navegou em uma Categoria que Baixou de Preço','Redução de Preços: Visualizou um Produto que Baixou de Preço','Tendências: Navegou em uma Categoria com Produtos em Alta']::text[], 5) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h7', 'Relatórios de Performance', 'Conjunto completo de relatórios para acompanhamento da performance das comunicações enviadas pela plataforma.', array['migracao']::text[], 'a-avaliar', null, null, array['Relatórios de Envio — e-mail, WhatsApp, SMS, Push, Web Push, App Push, On-site, Lightbox e Repiques','Relatórios de Interação — ranking de assuntos, fidelidade de abertura, Teste A/B','Relatórios Transacionais — Workflow e API','Relatório de Performance Geral — receita gerada pelas campanhas','Relatório de Performance de Envios Automáticos — réguas automáticas ativas','Reputação de Provedores — Gmail, Hotmail','Relatório de On-site e Web Push — métricas por campanha']::text[], 6) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h8', 'SMS', 'Novo canal de envio via SMS, permitindo disparos pontuais e automáticos para a base de clientes.', array['migracao']::text[], 'a-avaliar', null, null, null, 7) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h9', 'Wake U — Agenda do Vendedor', 'Sistema de oportunidades de venda direcionadas ao time de loja física, permitindo contatos ativos com clientes com base em dados da CDP — como aniversariantes, clientes inativos ou compradores recentes.', array['migracao']::text[], 'a-avaliar', null, null, null, 8) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h10', 'Matriz RFV (RFM)', 'Segmentação automática da base de clientes com base nos critérios de Recência, Frequência e Valor de compra, identificando perfis mais valiosos e criando estratégias personalizadas para cada grupo.', array['migracao']::text[], 'a-avaliar', null, null, null, 9) on conflict (id) do nothing;
