insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h12', 'Teste A/B', 'Criação e análise de testes de variação para campanhas e conteúdos, permitindo otimizar assuntos, templates e audiências.', array['migracao']::text[], 'a-avaliar', null, null, null, 11) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h13', 'Envios Transacionais', 'Disparos automáticos de e-mail e WhatsApp baseados em eventos transacionais, como confirmação de pedido, nota fiscal e atualizações de status.', array['migracao']::text[], 'a-avaliar', null, null, null, 12) on conflict (id) do nothing;
