insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h15', 'E-mail Inteligente', 'Templates de e-mail com personalização dinâmica baseada em IA, adaptando conteúdo e recomendações ao perfil de cada cliente.', array['migracao']::text[], 'a-avaliar', null, null, null, 14) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h16', 'Workflow', 'Criação de jornadas de comunicação automatizadas e multicanal, baseadas no engajamento e comportamento do usuário.', array['migracao']::text[], 'a-avaliar', null, null, array['Criação de jornadas com múltiplos passos, canais e condições','Gatilhos baseados em comportamento e engajamento do usuário (abertura, clique, compra, etc.)','Ramificações condicionais para personalização da jornada por perfil de resposta','Suporte a e-mail e WhatsApp na mesma jornada']::text[], 15) on conflict (id) do nothing;
