insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h24', 'Novos Filtros na Tela de Visão de Clientes', 'Evolução da tela de visão de clientes com novos critérios de filtragem, permitindo que o usuário faça combinações mais precisas para segmentar e analisar sua base diretamente na tela.', array['evolucao','cdp']::text[], 'a-avaliar', null, null, array['Filtro por ticket médio','Filtro por LTV','Filtro por audiência']::text[], 17) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h23', 'Córtex para Segmentos', 'Refinamento e finalização do Córtex aplicado ao Segmentador, atualmente implementado com dados mocados. Inclui a evolução da inteligência do Córtex para enriquecer segmentos com dados reais e ampliar suas capacidades analíticas.', array['evolucao','cdp']::text[], 'a-avaliar', null, null, array['Substituição dos dados mocados por dados reais na integração com o Córtex','Refinamento da experiência e dos resultados gerados pelo Córtex no Segmentador','Evolução das capacidades analíticas do Córtex para segmentos']::text[], 18) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h22', 'Receita e exportações CSV nas campanhas', 'Concluir a disponibilização de receita por campanha e as exportações de relatórios CSV (envios pontuais, automáticos e segmentos) via central de notificações.', array['migracao']::text[], 'planejado', null, null, array['Receita por campanha disponível nos relatórios','Exportação CSV de envios pontuais','Exportação CSV de envios automáticos','Exportação CSV de segmentos','Distribuição via central de notificações']::text[], 19) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h21', 'Adaptação do SDK para Aplicativos Mobile', 'Desenvolvimento e adaptação do SDK para instalação em aplicativos mobile, permitindo que clientes que operam com app próprio possam capturar navegação, eventos e dados dos seus clientes diretamente do aplicativo e enviá-los à CDP da Wake Experience 2.0.', array['evolucao','cdp']::text[], 'a-avaliar', null, null, array['SDK compatível com aplicativos mobile (iOS e Android)','Captura de eventos de navegação e comportamento dentro do app','Envio de dados de clientes do app para a CDP','Unificação do perfil do cliente entre web e app']::text[], 20) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h20', 'Relatório de Segmento', 'Área dedicada dentro do Segmentador para visualização detalhada de qualquer segmento — predefinido ou criado pelo usuário. Permite monitorar o tamanho da audiência, sua evolução ao longo do tempo e quem são os clientes dentro daquele segmento.', array['evolucao']::text[], 'a-avaliar', null, null, array['Visão do total de pessoas dentro de um segmento','Evolução histórica do segmento (crescimento ou queda)','Lista de clientes que compõem o segmento','Suporte a segmentos predefinidos e segmentos criados pelo usuário']::text[], 21) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h19', 'Captação de Device e Sistema Operacional pelo SDK', 'O SDK deve captar e armazenar o device e sistema operacional do cliente, tornando esse dado um critério segmentável e visível no perfil de cada cliente. Permite saber de onde a compra veio e onde ele navegou, habilitando promoções e condições de pagamento específicas por canal e sistema operacional.', array['evolucao','cdp']::text[], 'a-avaliar', null, array['Ybera']::text[], array['Captação de device (mobile, desktop, tablet) e sistema operacional via SDK','Dado disponível como critério de segmentação no Segmentador','Exibição no perfil único do cliente (canal de navegação e canal de compra)','Viabilizar promoções e condições de pagamento específicas por canal e SO']::text[], 22) on conflict (id) do nothing;
insert into public.hypotheses (id, title, description, type, status, previsao, cliente_tags, subitems, sort_order) values ('h18', 'Acesso Independente de Plataforma de E-commerce', 'Foco será em Wake Commerce. Clientes com outras plataformas (VTEX, Shopify, Magento) poderiam utilizar a plataforma de forma independente, sem necessidade de vínculo com o Wake Commerce.', array['evolucao']::text[], 'a-avaliar', null, null, array['Cadastro e acesso à plataforma sem integração com Wake Commerce','Compatibilidade com as principais plataformas de e-commerce do mercado','Mesmas funcionalidades disponíveis para todos os clientes, independente da plataforma utilizada']::text[], 23) on conflict (id) do nothing;
